// Local only: uses sessions generated by zones.integration.mjs, never production credentials.
const {chromium}=await import(process.env.PLAYWRIGHT_MODULE||'playwright');
import {readFileSync,mkdirSync} from 'node:fs';
import assert from 'node:assert/strict';
const session=JSON.parse(readFileSync('output/zones-test-session.json','utf8'));
assert.equal(new URL(session.base).hostname,'127.0.0.1');
session.base=session.base.replace('127.0.0.1','localhost');
(async()=>{
 const browser=await chromium.launch({headless:true});
 const context=await browser.newContext({viewport:{width:1440,height:1000}});await context.addCookies([{name:'aa_session',value:session.admin,url:session.base}]);
 const page=await context.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto(session.base+'/cartera');await page.getByRole('button',{name:/^Chimbote\s/}).waitFor({timeout:60000});
 assert.equal(await page.locator('aside a[href^="/registrar-inmueble"]').count(),0);
 mkdirSync('output/zones-browser',{recursive:true});await page.screenshot({path:'output/zones-browser/general-desktop.png',fullPage:true});
 await page.getByRole('button',{name:/^Chimbote\s/}).click();await page.waitForURL(/zona=Chimbote/);await page.locator('aside a[href^="/registrar-inmueble"]').waitFor();
 await page.getByRole('button',{name:'Tarjetas',exact:true}).click();await page.locator('[data-folder-card="true"]').last().waitFor();assert.equal(await page.locator('[data-folder-card="true"]').count(),50);
 await page.screenshot({path:'output/zones-browser/chimbote-cards.png',fullPage:true});
 await page.locator('aside a[href^="/registrar-inmueble"]').click();await page.getByLabel(/Ubicación referencial/).waitFor({timeout:60000});assert.ok(page.url().includes('zona=Chimbote'));
 assert.equal(await page.locator('select').filter({has:page.locator('option',{hasText:'Seleccionar departamento'})}).count(),0);
 await page.getByLabel(/^Posición en esta zona/).locator('option').nth(44).waitFor({state:'attached',timeout:60000});
 assert.equal(await page.getByLabel(/^Posición en esta zona/).locator('option').count(),45);
 await page.screenshot({path:'output/zones-browser/registration-chimbote.png',fullPage:true});
 await page.locator('aside a[href^="/visitas-pendientes"]').click();await page.getByRole('heading',{name:'Visitas pendientes',exact:true}).waitFor({timeout:60000});assert.ok(page.url().includes('zona=Chimbote'));
 await page.locator('aside a',{hasText:'Todas las zonas'}).click();await page.getByRole('button',{name:/^Nuevo Chimbote\s/}).waitFor();assert.equal(await page.locator('aside a[href^="/registrar-inmueble"]').count(),0);
 await page.getByRole('button',{name:/^Nuevo Chimbote\s/}).click();await page.waitForURL(/zona=Nuevo/);await page.getByRole('button',{name:'Tarjetas',exact:true}).click();await page.locator('[data-folder-card="true"]').last().waitFor();assert.equal(await page.locator('[data-folder-card="true"]').count(),90);
 await page.locator('aside a[href^="/reportes"]').click();await page.getByLabel('Zona del reporte').waitFor({timeout:60000});assert.equal(await page.getByLabel('Zona del reporte').inputValue(),'Nuevo Chimbote');
 await page.getByLabel('Zona del reporte').selectOption('*');await page.waitForURL(url=>!url.searchParams.has('zona'));assert.equal(await page.locator('aside a[href^="/registrar-inmueble"]').count(),0);
 await page.setViewportSize({width:375,height:850});await page.goto(session.base+'/cartera');await page.getByRole('button',{name:/^Tortugas\s/}).waitFor();await page.getByRole('button',{name:/^Tortugas\s/}).click();await page.waitForURL(/zona=Tortugas/);await page.getByRole('button',{name:'Abrir menú'}).click();await page.locator('aside a[href^="/registrar-inmueble"]').waitFor();
 await page.screenshot({path:'output/zones-browser/tortugas-mobile-menu.png',fullPage:true});assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);
 const operator=await browser.newContext();await operator.addCookies([{name:'aa_session',value:session.operator,url:session.base}]);const userPage=await operator.newPage();await userPage.goto(session.base+'/datos-inmuebles');await userPage.locator('aside a[href^="/datos-inmuebles"]').waitFor({timeout:60000});assert.equal(await userPage.locator('aside a[href^="/registrar-inmueble"]').count(),0);assert.equal(await userPage.locator('aside a[href^="/cartera"]').count(),0);
 assert.deepEqual(errors,[]);await browser.close();console.log('Navegación visual correcta: menú contextual y retorno general, tarjetas 50/90, captación sin geografía, reportes por zona, móvil sin desbordes y operador conservado.');
})().catch(e=>{console.error(e);process.exitCode=1;process.exit(1)});
